import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"1","title":"Home","prev":null,"next":"/page/2/","posts":[{"title":"如何比较版本号","url":"/posts/2024-07-02-compare-version/","date":"2024-07-02 21:52","tags":["web"],"html":"<p>前端代码需要运行在客户的浏览器中，但是有些版本的浏览器不支持某些特性，所以我们需要比较浏览器的版本号，然后根据版本号来决定是否使用某些特性。这里就涉及到版本号的比较问题。</p>\\n<h2 id=\\"版本号定义\\" tabindex=\\"-1\\">版本号定义 <a class=\\"header-anchor\\" href=\\"#版本号定义\\" aria-label=\\"Permalink to &quot;版本号定义&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>版本号一般是由三个数字组成，分别是主版本号、次版本号和修订版本号。比如 <code>1.2.3</code>，其中 <code>1</code> 是主版本号，<code>2</code> 是次版本号，<code>3</code> 是修订版本号。版本号的比较是从左到右依次比较，如果左边的数字相等，再比较右边的数字。但是版本号有些只有两个数字，比如 <code>1.2</code>，这时候我们可以认为修订版本号是 0，所以 <code>1.2</code> 等价于 <code>1.2.0</code>。</p>\\n<h2 id=\\"两个版本号比较\\" tabindex=\\"-1\\">两个版本号比较 <a class=\\"header-anchor\\" href=\\"#两个版本号比较\\" aria-label=\\"Permalink to &quot;两个版本号比较&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这里我们需要把版本号转换成数组，然后比较两个数组的大小。如果两个数组的长度不一样，我们可以认为长度短的数组后面都是 0。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> compareVersions</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">v1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">[], </span><span style=\\"color:#E36209\\">v2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">[])</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">let</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> Math.</span><span style=\\"color:#6F42C1\\">max</span><span style=\\"color:#24292E\\">(v1.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">, v2.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">); i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> num1</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> v1[i] </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> num2</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> v2[i] </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (num1 </span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#24292E\\"> num2) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (num1 </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> num2) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#D73A49\\"> -</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>如果我们需要判断版本号是否在某个范围内，我们可以这样写：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> isVersionInRange</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  version</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">[],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  min</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">[],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  max</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">[]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    compareVersions</span><span style=\\"color:#24292E\\">(version, min) </span><span style=\\"color:#D73A49\\">>=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> compareVersions</span><span style=\\"color:#24292E\\">(version, max) </span><span style=\\"color:#D73A49\\">&#x3C;=</span><span style=\\"color:#005CC5\\"> 0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>版本号比较虽然看起来简单，但是在实现过程中还是需要考虑各种情况，例如版本号的长度不一样，版本号的范围判断等。</p>\\n"},{"title":"编译 zbar 到 WebAssembly","url":"/posts/2024-06-01-zbar-wasm/","date":"2024-06-01 16:06","tags":["WebAssembly"],"html":"<p>工作上需要前端实现扫描二维码的功能，这部分属于图像识别的工作，图像识别相关的库基本都是 C 语言库，所以需要将这些库编译到 WebAssembly，然后在前端调用。</p>\\n<h2 id=\\"胶水函数\\" tabindex=\\"-1\\">胶水函数 <a class=\\"header-anchor\\" href=\\"#胶水函数\\" aria-label=\\"Permalink to &quot;胶水函数&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们需要将 C 语言的函数暴露出来，这样前端才能调用这些函数，这部分代码称为胶水函数。下面列举了一个简单的例子。</p>\\n<div class=\\"language-c line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">c</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;emscripten.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;zbar.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;stdio.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;stdlib.h></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#define</span><span style=\\"color:#6F42C1\\"> EXPORT</span><span style=\\"color:#24292E\\"> EMSCRIPTEN_KEEPALIVE</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typedef</span><span style=\\"color:#D73A49\\"> int</span><span style=\\"color:#D73A49\\"> int32_t</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typedef</span><span style=\\"color:#D73A49\\"> unsigned</span><span style=\\"color:#D73A49\\"> int</span><span style=\\"color:#D73A49\\"> uint32_t</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EXPORT </span><span style=\\"color:#005CC5\\">zbar_image_scanner_t</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#6F42C1\\"> ImageScanner_create</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> zbar_image_scanner_create</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><h3 id=\\"编写-makefile\\" tabindex=\\"-1\\">编写 Makefile <a class=\\"header-anchor\\" href=\\"#编写-makefile\\" aria-label=\\"Permalink to &quot;编写 Makefile&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-makefile line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">makefile</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_VERSION = 0.23.90</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_SRC = zbar-</span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_VERSION</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">SRC = src</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">BUILD = build</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">DIST = dist</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EM_VERSION = 3.1.44</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># See https://emscripten.org/docs/tools_reference/emcc.html</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCC = emcc</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMMAKE = emmake</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCONFIG = emconfigure</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_DEPS = </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/make.done</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_OBJS = </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar/*.o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar/*/*.o</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_INC = -I </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/include/ -I </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># See https://github.com/emscripten-core/emscripten/blob/main/src/settings.js</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCC_FLAGS = -Oz -Wall -Werror -s ALLOW_MEMORY_GROWTH=1 </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t-s EXPORTED_FUNCTIONS=\\"['_malloc','_free']\\" </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t-s MODULARIZE=1 -s EXPORT_NAME=zbarWasm</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">.PHONY</span><span style=\\"color:#24292E\\">: all build clean-build clean</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">all</span><span style=\\"color:#24292E\\">: build</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">build</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.wasm</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">clean-build</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm -rf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">DIST</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">clean</span><span style=\\"color:#24292E\\">: clean-build</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm -rf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.wasm </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/export.c</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tmkdir -p </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">\\t$(</span><span style=\\"color:#24292E\\">EMCC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">EMCC_FLAGS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> -o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js -sEXPORT_ES6 </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/export.c </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_INC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">ZBAR_OBJS</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/Makefile</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcd </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> &#x26;&#x26; </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">EMMAKE</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> make CFLAGS=-Os CXXFLAGS=-Os </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\tDEFS=\\"-DZNO_MESSAGES -DHAVE_CONFIG_H\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttouch -m </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/Makefile: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcd </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> &#x26;&#x26; </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">EMCONFIG</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> ./configure --without-x --without-xshm </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-xv --without-jpeg --without-libiconv-prefix </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-imagemagick --without-npapi --without-gtk </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-python --without-qt --without-xshm --disable-video </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--disable-pthread --disable-assert --host=x86_64-linux-gnu</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttar zxvf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttouch -m </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcurl -L -o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz https://linuxtv.org/downloads/zbar/zbar-</span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_VERSION</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br></div></div><p>Makefile 中定义了编译 zbar 的流程，我们首先使用 curl 下载 zbar 的源码，然后解压，然后配置编译参数，最后编译生成 zbar 的调用 JS 和 WASM 文件。注意在配置参数中我们禁用了一些功能，因为这些功能在 WebAssembly 中不需要，并且在指定 host 的时候需要根据运行环境设置正确的参数，如果是运行在 Github Actions 中，需要设置为 <code>x86_64-linux-gnu</code>。如果是 M1 芯片的 Mac，需要设置为 <code>arm</code>。</p>\\n<h3 id=\\"函数封装\\" tabindex=\\"-1\\">函数封装 <a class=\\"header-anchor\\" href=\\"#函数封装\\" aria-label=\\"Permalink to &quot;函数封装&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>虽然我们从 zbar 暴露出来关键的图像处理相关的函数，但是用起来还不是那么方便，所以我们需要写一点 Typescript 的代码来封装这些函数。然后使用 rollup 打包成 JS 文件，并生成对应的 TS 类型文件。这部分实现细节就不赘述了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>编译 zbar 到 WebAssembly 的过程并不复杂，但是需要注意一些细节，比如编译参数的设置，胶水函数的编写等。这部分工作需要一定的 C 语言基础，如果没有的话，可以参考一些现成的例子，然后根据自己的需求进行修改。我也是参考网上的例子，然后根据自己的需求进行修改的。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/undecaf/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">undecaf/zbar-wasm</a></p>\\n<p><a href=\\"https://github.com/acgotaku/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">acgotaku/zbar-wasm</a></p>\\n"},{"title":"前端的缓存策略","url":"/posts/2024-03-13-cache-control/","date":"2024-03-13 21:58","tags":["web"],"html":"<p>前端资源也需要配置缓存策略，以提高网站的访问速度。由于网站的流量增大，我们需要合适的缓存策略才能让 CDN 发挥最大效果保证网站的访问速度。</p>\\n<h2 id=\\"cache-control\\" tabindex=\\"-1\\">Cache-Control <a class=\\"header-anchor\\" href=\\"#cache-control\\" aria-label=\\"Permalink to &quot;Cache-Control&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Cache-Control 用来设置资源的缓存策略，常见的的值有：no-store 、no-cache、public、private、max-age、immutable。</p>\\n<h3 id=\\"no-store\\" tabindex=\\"-1\\">no-store <a class=\\"header-anchor\\" href=\\"#no-store\\" aria-label=\\"Permalink to &quot;no-store&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>不缓存资源，每次都需要重新请求。</p>\\n<h3 id=\\"no-cache\\" tabindex=\\"-1\\">no-cache <a class=\\"header-anchor\\" href=\\"#no-cache\\" aria-label=\\"Permalink to &quot;no-cache&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>需要先验证资源是否过期，如果没有过期，可以使用缓存。</p>\\n<h3 id=\\"public\\" tabindex=\\"-1\\">public <a class=\\"header-anchor\\" href=\\"#public\\" aria-label=\\"Permalink to &quot;public&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>资源可以被所有的用户缓存，包括 CDN。</p>\\n<h3 id=\\"private\\" tabindex=\\"-1\\">private <a class=\\"header-anchor\\" href=\\"#private\\" aria-label=\\"Permalink to &quot;private&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>资源只能被用户缓存，不能被 CDN 缓存。</p>\\n<h3 id=\\"max-age\\" tabindex=\\"-1\\">max-age <a class=\\"header-anchor\\" href=\\"#max-age\\" aria-label=\\"Permalink to &quot;max-age&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>设置资源的最大缓存时间，单位是秒。</p>\\n<h3 id=\\"immutable\\" tabindex=\\"-1\\">immutable <a class=\\"header-anchor\\" href=\\"#immutable\\" aria-label=\\"Permalink to &quot;immutable&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>资源不会改变，可以永久缓存。</p>\\n<h2 id=\\"前端网站的缓存策略\\" tabindex=\\"-1\\">前端网站的缓存策略 <a class=\\"header-anchor\\" href=\\"#前端网站的缓存策略\\" aria-label=\\"Permalink to &quot;前端网站的缓存策略&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在的前端网站一般都是 SPA 或者 PWA，index.html 是一个入口文件，其他的资源都是通过 index.html 加载的。所以我们可以设置 index.html 的缓存策略为 no-store，保证每次都是最新的资源。</p>\\n<p>其他的都是静态资源，并且文件名包含 hash，所以我们可以设置这些资源的缓存策略为 immutable，保证这些资源不会改变，可以永久缓存。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">Cache-Control:</span><span style=\\"color:#032F62\\"> no-store</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Cache-Control:</span><span style=\\"color:#032F62\\"> public,</span><span style=\\"color:#032F62\\"> max-age=604800,</span><span style=\\"color:#032F62\\"> immutable</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>index.html 文件是网站入口，这个文件不能缓存，每次都需要重新请求，否则不能及时更新网站。不过这个文件一般也不大，所以不会影响网站的访问速度。其他的静态资源文件名包含 hash，所以这些资源不会改变，可以永久缓存，这样可以提高网站的访问速度。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control\\" target=\\"_blank\\" rel=\\"noreferrer\\">MDN Cache-Control</a></p>\\n<p><a href=\\"https://web.dev/articles/http-cache\\" target=\\"_blank\\" rel=\\"noreferrer\\">Prevent unnecessary network requests with the HTTP Cache</a></p>\\n"}]},"relativePath":"index.md","filePath":"page/[page].md"}`),l={name:"index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
